-- ============================================================================
INSERT INTO SCM_MGR.SCM_MST_SITE (DIVISION_ID, SCM_SITE_ID, PLANT_ID, OPERATION_GROUP, SITE_DESCRIPTION, SITE_TYPE, CITY, COUNTRY, VMI_YN, VALID_YN, NEW_YN, SITE_HRCY_ID, OSP_YN, SHIP_FROZEN, PROD_FROZEN, END_CUSTOMER, SOLDTO_CUSTOMER, FP_PLAN_PERIOD, BUILD_AHEAD, LOGISTIC_PLANT_ID, PACKER_ITEM_ID_SUFFIX, HQ_VENDOR_CODE, COMPANY_ID, SITE_ID, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, DEPT_ID)
SELECT '40', 'BYD Electronics_CN_SZX', NULL, NULL, 'BYD Electronics_CN_SZX', 'SALES', 'CNSZX', 'CN', 'N', 'Y', 'Y', NULL, NULL, NULL, NULL, '-', 'BYD Electronics', NULL, NULL, NULL, NULL, NULL, 'HQ00', NULL, 'jenny.k', TO_DATE('2026-04-21 16:03:49','YYYY-MM-DD HH24:MI:SS'), 'jenny.k', TO_DATE('2026-04-21 16:03:49','YYYY-MM-DD HH24:MI:SS'), NULL, 'Y', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '-' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_MST_SITE X
                  WHERE X.DIVISION_ID='40' AND X.SCM_SITE_ID='BYD Electronics_CN_SZX');

COMMIT;
